-- PT115-S4-Q5. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT115-S4-Q5$batch03$ AND q.stimulus=$batch03$Lactose, a sugar found in milk, aids in the absorption of calcium, which in turn is required for bone repair. In addition to there being shortages of milk in tropical areas, inhabitants of these areas lose the ability to absorb lactose, unlike people from nontropical areas. Yet inhabitants of tropical areas have no more problems with bone repair than do people who inhabit nontropical areas.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to resolve the apparent paradox described above?$batch03$ AND q.correct_choice=$batch03$C$batch03$) THEN RAISE EXCEPTION 'Question changed: PT115-S4-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT115-S4-Q5$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S4-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT115-S4-Q5$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Lactose helps calcium absorption, which bone repair needs. People in tropical areas have little milk and lose the ability to absorb lactose.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$They have no more trouble with bone repair than people elsewhere?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Lactose is one way to absorb calcium. If tropical people have another way, they would not need it. Think about what the tropics have plenty of.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find another source of help absorbing calcium that tropical people have.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT115-S4-Q5$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Lactose tablets do not help people who have lost the ability to absorb lactose.$batch03$), ($batch03$B$batch03$, $batch03$Lower milk consumption everywhere does not separate tropical from nontropical people.$batch03$), ($batch03$C$batch03$, $batch03$Abundant sunlight makes the body produce vitamin D, which helps absorb calcium. Tropical people get calcium absorption another way.$batch03$), ($batch03$D$batch03$, $batch03$A slight rise in other dairy products does not fix calcium absorption for people who cannot absorb lactose, and "slightly" could not close the gap.$batch03$), ($batch03$E$batch03$, $batch03$Genetics deciding how much the ability is lost does not explain how bone repair stays normal.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT115-S4-Q5$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
